package io.github.blanaboo.stimmzug.dsp.synth

import io.github.blanaboo.stimmzug.dsp.music.NoteMath
import io.github.blanaboo.stimmzug.dsp.signal.SignalMath
import kotlin.math.max
import kotlin.math.min

/**
 * Harmonic levels of a real tuba, measured note by note from a recording of held notes (#72), so the drone sounds
 * like the player's own instrument. The table is generated by the replay tool (`--spectrum`), see
 * `docs/drone-klang.md`.
 *
 * A drone takes the levels of the nearest measured note: below and above the measured range those of the lowest or
 * highest note. The concert pitch does not matter for the choice, 430–450 Hz stay within ±50 ct of the note at
 * 440 Hz.
 */
class MeasuredSpectrum(
    /** The instrument, e.g. "B&S GR55". */
    val name: String,
    /** MIDI number of the first entry of [levelsDb]. */
    val lowestMidi: Int,
    /**
     * Chromatically from [lowestMidi]: levels of harmonics 1..n in dB relative to the strongest one
     * (index 0 = fundamental).
     */
    val levelsDb: List<DoubleArray>
) {
    init {
        require(levelsDb.isNotEmpty()) { "need at least one note" }
        require(levelsDb.all { it.isNotEmpty() }) { "every note needs at least its fundamental" }
    }

    val highestMidi: Int get() = lowestMidi + levelsDb.size - 1

    /** The levels used for a drone on [frequencyHz]. */
    fun levelsFor(frequencyHz: Double): DoubleArray {
        require(frequencyHz > 0.0) { "frequency must be positive, was $frequencyHz" }
        val midi = NoteMath.nearestMidi(frequencyHz).coerceIn(lowestMidi, highestMidi)
        return levelsDb[midi - lowestMidi]
    }

    /**
     * Linear amplitudes of harmonics 1..n for a drone on [fundamentalHz], normalized to a maximum of 1; like
     * [TubaSpectrum.harmonicAmplitudes] limited to [maxFrequencyHz] and to 45 % of [sampleRate] (no aliasing).
     */
    fun harmonicAmplitudes(fundamentalHz: Double, sampleRate: Double, maxFrequencyHz: Double = 6000.0): DoubleArray {
        val levels = levelsFor(fundamentalHz)
        val limit = min(maxFrequencyHz, NYQUIST_SHARE * sampleRate)
        val count = max(1, min(levels.size, (limit / fundamentalHz).toInt()))
        val amplitudes = DoubleArray(count) { SignalMath.dbToAmplitude(levels[it]) }
        val peak = amplitudes.max()
        return DoubleArray(count) { amplitudes[it] / peak }
    }

    companion object {
        private const val NYQUIST_SHARE = 0.45

        /** Parses levels written as whole dB separated by spaces, split over several strings for line length. */
        fun levels(vararg parts: String): DoubleArray =
            parts.joinToString(" ").trim().split(Regex("\\s+")).map { it.toDouble() }.toDoubleArray()
    }
}
